        return INVALID_HANDLE_VALUE;
    }
    return hPipe;
}

// Function to send data through the named pipe
void sendDataThroughPipe(HANDLE hPipe, const char* data, int dataSize) {
    DWORD bytesWritten;
    if (!WriteFile(hPipe, data, dataSize, &bytesWritten, NULL)) {
        std::cerr << "Failed to write to named pipe." << std::endl;
    }
}

// Function to receive data from the named pipe
void receiveDataFromPipe(HANDLE hPipe, char* data, int dataSize) {
    DWORD bytesRead;
    if (!ReadFile(hPipe, data, dataSize, &bytesRead, NULL)) {
        std::cerr << "Failed to read from named pipe." << std::endl;
    }
}

