#include <Windows.h>
#include <stdio.h>
#include <iostream>
#include <string>

// Function to create a named pipe
HANDLE CreateNamedPipe(const wchar_t* name, DWORD mode, DWORD size, DWORD outBuffer, DWORD inBuffer, DWORD timeOut, LPSECURITY_ATTRIBUTES secAttr, LPSTARTUPINFO* startInfo)
{
    HANDLE hPipe = CreateNamedPipeA(name, mode, secAttr, size, inBuffer, timeOut, startInfo);
    if (hPipe == INVALID_HANDLE_VALUE)
    {
        return INVALID_HANDLE_VALUE;
    }
    return hPipe;
}

// Function to connect to a named pipe
HANDLE ConnectToNamedPipe(HANDLE hPipe, LPSECURITY_ATTRIBUTES secAttr, LPSTARTUPINFO* startInfo)
{
    HANDLE hConn = CreateFileA("\\\\.\\pipe\\", GENERIC_READ | GENERIC_WRITE, 0, secAttr, OPEN_EXISTING, 0, NULL);
    if (hConn == INVALID_HANDLE_VALUE)
    {
        return INVALID_HANDLE_VALUE;
    }
    ConnectNamedPipe(hConn, hPipe, startInfo);
    return hConn;
}

// Function to disconnect from a named pipe
void DisconnectFromNamedPipe(HANDLE hConn)
{
    CloseHandle(hConn);
}

// Function to send data through a named pipe
BOOL SendDataThroughNamedPipe(HANDLE hConn, const char* data, DWORD dataSize)
{
    DWORD bytesWritten;
    if (!WriteFile(hConn, data, dataSize, &bytesWritten, NULL))
    {
        return FALSE;
    }
    return TRUE;
}

// Function to receive data from a named pipe
BOOL ReceiveDataFromNamedPipe(HANDLE hConn, char* data, DWORD dataSize)
{
    DWORD bytesReceived;
    if (!ReadFile(hConn, data, dataSize, &bytesReceived, NULL))
    {
        return FALSE;
    }
    return TRUE;
}

