```cpp
#include <Windows.h>
#include <iostream>
#include <string>
#include <mutex>
#include <semaphore.h>

// Constants
const std::string PIPE_NAME = "my_named_pipe";
const int BUFFER_SIZE = 1024;

// Mutex and semaphore handles
std::mutex mtx;
sem_t sem;

// Function to create the named pipe
bool createNamedPipe() {
    // Create a named pipe with the specified name
    HANDLE hPipe = CreateNamedPipe(
        PIPE_NAME.c_str(),
        PIPE_ACCESS_DUPLEX,
        PIPE_TYPE_BYTE | PIPE_READMODE_BYTE | PIPE_WAIT,
        1,
        BUFFER_SIZE,
        BUFFER_SIZE,
        0,
        NULL
    );

    // Check if the pipe was created successfully
    if (hPipe == INVALID_HANDLE_VALUE) {
        std::cerr << "Error creating named pipe: " << GetLastError() << std::endl;
        return false;
    }

    // Initialize the mutex and semaphore
    sem_init(&sem, 0, 0);
    sem_init(&mtx, 0, 1);

    return true;
}

// Function to send data to the pipe
bool sendDataToPipe(const std::string& data) {
    // Acquire the mutex
    mtx.lock();

    // Write data to the pipe
    DWORD bytesWritten;
    if (!WriteFile(hPipe, data.c_str(), data.size(), &bytesWritten, NULL)) {
        std::cerr << "Error writing to pipe: " << GetLastError() << std::endl;
        return false;
    }

    // Release the mutex
    mtx.unlock();

    // Increment the semaphore
    sem_post(&sem);

    return true;
}

// Function to receive data from the pipe
bool receiveDataFromPipe() {
    // Acquire the semaphore
    sem_wait(&sem);

    // Read data from the pipe
    char buffer[BUFFER_SIZE];
    DWORD bytesRead;
    if (!ReadFile(hPipe, buffer, BUFFER_SIZE, &bytesRead, NULL)) {
        std::cerr << "Error reading from pipe: " << GetLastError() << std::endl;
        return false;
    }

    // Process the received data
    std::string receivedData(buffer, bytesRead);

    // Release the mutex
    mtx.unlock();

    return true;
}

int main() {
    // Create the named pipe
    if (!createNamedPipe()) {
        return 1;
    }

    // Send data to the pipe
    std::string data = "Hello, world!";
    if (!sendDataToPipe(data)) {
        return 1;
    }

    // Receive data from the pipe
    if (!receiveDataFromPipe()) {
        return 1;
    }

    std::cout << "Received data: " << data << std::endl;

    // Close the pipe
    CloseHandle(hPipe);

    return 0;
}
