// peer.js
const { RTCPeerConnection } = require('webrtc');
const { createOffer, createAnswer } = require('webrtc');

class Peer {
  constructor() {
    this.pc = new RTCPeerConnection();
    this.localStream = null;
    this.remoteStream = null;
  }

  async connect() {
    try {
      await this.pc.createOffer();
      const offer = await this.pc.createOffer();
      await this.pc.setLocalDescription(new RTCSessionDescription({ type: 'offer', sdp: offer }));
      await this.pc.setRemoteDescription(new RTCSessionDescription({ type: 'offer', sdp: offer }));

