    HANDLE hPipe = CreateNamedPipeA(name, mode, size, outBuffer, inBuffer, securityAttributes, secAttrs, startInfo);
    return hPipe;
}

// Function to connect to a named pipe
HANDLE ConnectNamedPipe(HANDLE hPipe, LPSECURITY_ATTRIBUTES secAttrs, LPSTARTUPINFOA startInfo, LPVOID buffer, DWORD size)
{
    // Connect to the named pipe
    HANDLE hConn = ConnectNamedPipe(hPipe, secAttrs, startInfo, buffer, size);
    return hConn;
}

// Function to send data to the pipe
