}

// Function to receive data from the pipe
BOOL ReceiveFileFromPipe(HANDLE hConn, LPVOID buffer, DWORD size)
{
    // Receive data from the pipe
    return ReceiveFile(hConn, buffer, size, NULL, NULL);
}

int main()
{
    // Create a named pipe
    const wchar_t* pipeName = L"\\\\.\\pipe\\myPipe";
    DWORD mode = PIPE_ACCESS_DUPLEX | PIPE_TYPE_BYTE | PIPE_READMODE_BYTE | PIPE_WAIT;
    DWORD size = 1024;
    LPSECURITY_ATTRIBUTES secAttrs = NULL;
    LPSTARTUPINFOA startInfo = NULL;
