**Named Pipe Example**

This example will create a named pipe, connect to it from a parent process, and then transfer a file from the child process to the parent process.

**Parent Process (main.cpp)**
```cpp
#include <Windows.h>
#include <iostream>
#include <fstream>

int main() {
    // Create a named pipe
    HANDLE hPipe = CreateNamedPipe(
        L"\\\\.\\pipe\\myPipe",
        PIPE_ACCESS_DUPLEX | PIPE_TYPE_BYTE | PIPE_READMODE_BYTE | PIPE_WAIT,
        1, 1, 1024, 1024, NULL, NULL
    );

    if (hPipe == INVALID_HANDLE_VALUE) {
        std::cerr << "Failed to create named pipe" << std::endl;
        return 1;
    }

    // Connect to the named pipe
    HANDLE hConn = ConnectNamedPipe(hPipe, NULL);

    if (hConn == INVALID_HANDLE_VALUE) {
        std::cerr << "Failed to connect to named pipe" << std::endl;
        CloseHandle(hPipe);
        return 1;
    }

    // Create a file to send
    std::ofstream file("file.txt");
    if (!file.is_open()) {
        std::cerr << "Failed to open file" << std::endl;
        CloseHandle(hConn);
        CloseHandle(hPipe);
        return 1;
    }

    // Write to the file
    file << "Hello, world!" << std::endl;

    // Close the file
    file.close();

    // Disconnect from the named pipe
    DisconnectNamedPipe(hConn);

    // Close the named pipe
    CloseHandle(hPipe);

    return 0;
}
```

