#import <Foundation/Foundation.h>
#import <CoreServices/CoreServices.h>

@interface FileMonitor : NSObject

@property (nonatomic, strong) NSString *targetFile;
@property (nonatomic, strong) NSFileHandle *fileHandle;

- (instancetype)initWithTargetFile:(NSString *)targetFile;

- (void)startMonitoring;

- (void)stopMonitoring;

- (void)fileChanged;

@end

@implementation FileMonitor

@synthesize targetFile = _targetFile;
@synthesize fileHandle = _fileHandle;

- (instancetype)initWithTargetFile:(NSString *)targetFile {
    self = [super init];
    if (self) {
        _targetFile = [targetFile copy];
        _fileHandle = [NSFileHandle fileHandleForReadingAtPath:_targetFile.path];
    }
    return self;
}

- (void)startMonitoring {
    NSFileSystemNotification *notification = [[NSFileSystemNotification alloc] init];
    notification.name = @"NSFSFileSystemChangedNotification";
    notification.infoKey = @"kFSFileSystemType";
    notification.infoValue = _targetFile.path;
    [[NSWorkspace sharedWorkspace] addNotification:notification];
    [[NSNotificationCenter defaultCenter] addObserver:self selector:@selector(fileChanged:) name:notification.name object:nil];
}

- (void)stopMonitoring {
    [[NSWorkspace sharedWorkspace] removeNotification:notification];
    [[NSNotificationCenter defaultCenter] removeObserver:self];
}

- (void)fileChanged {
    NSFileSystemNotification *notification = [[NSFileSystemNotification alloc] init];
    notification.name = @"NSFSFileSystemChangedNotification";
    notification.infoKey = @"kFSFileSystemType";
    notification.infoValue = _targetFile.path;
    [[NSWorkspace sharedWorkspace] addNotification:notification];
    [[NSNotificationCenter defaultCenter] addObserver:self selector:@selector(fileChanged:) name:notification.name object:nil];
    [self fileChanged];
}

- (void)fileChanged {
    NSFileHandle *fileHandle = [NSFileHandle fileHandleForReadingAtPath:_targetFile.path];
    if ([fileHandle isOpen]) {
        NSString *fileInfo = [fileHandle readDataOfLength:1024];
        if ([fileInfo containsString:@"modified"]) {
            // Trigger alert
            NSLog(@"File has changed!");
            // You can also trigger an alert here
        }
    }
}

@end
```

