The code is divided into two main parts:

1.  **Server-side (index.js)**: This script sets up a simple signaling server using Socket.IO. It handles incoming connections and broadcasts messages to all connected clients.
2.  **Client-side (index.html)**: This HTML file contains the WebRTC peer connection and data channel setup.

**Server-side (index.js)**
-------------------------

```javascript
const express = require('express');
const app = express();
const server = require('http').createServer(app);
const io = require('socket.io')(server);

let peers = {};

io.on('connection', (socket) => {
    console.log('New client connected');

    // Handle incoming messages from clients
    socket.on('message', (data) => {
        console.log(`Received message from ${socket.id}: ${data}`);
        // Broadcast the message to all connected clients
        io.emit('message', data);
    });

    // Handle peer connection establishment
    socket.on('peer-connection', (peer) => {
        console.log(`Peer connection established: ${peer.id}`);
        peers[peer.id] = peer;
    });

    // Handle peer disconnection
    socket.on('disconnect', () => {
        console.log('Client disconnected');
        delete peers[socket.id];
    });
});

server.listen(3000, () => {
    console.log('Server listening on port 3000');
});
```

**Client-side (index.html)**
---------------------------

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>WebRTC P2P Communication</title>
    <style>
        #video-container {
            width: 640px;
            height: 480px;
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <h1>WebRTC P2P Communication</h1>
    <div id="video-container">
        <video id="local-video" width="640" height="480"></video>
        <video id="remote-video" width="640" height="480"></video>
    </div>
    <script src="https://cdn.jsdelivr.net/npm/webrtc@1.0.0/dist/webrtc.min.js"></script>
    <script>
        const localVideo = document.getElementById('local-video');
        const remoteVideo = document.getElementById('remote-video');
        const peerConnection = new RTCPeerConnection();
        const dataChannel = peerConnection.createDataChannel('data');

        // Add local stream to peer connection
        navigator.mediaDevices.getUserMedia({ video: true })
            .then((stream) => {
                localVideo.srcObject = stream;
                peerConnection.addStream(stream);
            })
            .catch((error) => {
                console.error('Error getting user media:', error);
            });

        // Handle data channel messages
        dataChannel.onmessage = (event) => {
            console.log(`Received message from remote peer: ${event.data}`);
            remoteVideo.srcObject = event.data;
        };

        // Handle peer connection events
        peerConnection.onicecandidate = (event) => {
            if (event.candidate) {
                console.log(`ICE candidate: ${event.candidate}`);
                socket.emit('peer-connection', peerConnection);
            }
        };

        // Handle peer connection establishment
        peerConnection.onaddstream = (event) => {
            console.log(`Remote stream added: ${event.stream.id}`);
            remoteVideo.srcObject = event.stream;
        };

        // Handle peer disconnection
        peerConnection.onicecandidate = (event) => {
            if (event.candidate) {
                console.log(`ICE candidate: ${event.candidate}`);
                socket.emit('peer-connection', peerConnection);
            }
        };

        // Handle peer connection close
        peerConnection.onclose = () => {
            console.log('Peer connection closed');
            socket.emit('disconnect');
        };
    </script>
</body>
</html>
```

