HANDLE CreateNamedPipe(const wchar_t* name, DWORD mode, DWORD size, DWORD outBuffer, DWORD inBuffer, DWORD securityAttributes, LPSECURITY_ATTRIBUTES secAttrs, LPSTARTUPINFO* startInfo)
