BOOL SendDataThroughPipe(HANDLE hPipe, const wchar_t* data, DWORD dataSize)
{
    DWORD bytesWritten;
    if (!WriteFile(hPipe, data, dataSize, &bytesWritten, NULL))
    {
        DWORD errorCode = GetLastError();
        std::cerr << "Failed to write to pipe: " << errorCode << std::endl;
        return FALSE;
    }
    return TRUE;
}

// Function to receive data from the pipe
BOOL ReceiveDataThroughPipe(HANDLE hPipe, wchar_t* data, DWORD dataSize)
{
    DWORD bytesRead;
    if (!ReadFile(hPipe, data, dataSize, &bytesRead, NULL))
    {
        DWORD errorCode = GetLastError();
        std::cerr << "Failed to read from pipe: " << errorCode << std::endl;
        return FALSE;
    }
    return TRUE;
