BOOL AdjustTokenPrivileges(HANDLE hToken, BOOL DisableAll, PrivilegeSet *NewState) {
    TOKEN_PRIVILEGES tp;
    if (!GetTokenInformation(hToken, TokenPrivileges, &tp, sizeof(TOKEN_PRIVILEGES), NULL)) {
        return FALSE;
    }

    // Remove SeImpersonate privilege if it's currently enabled
    if (tp.PrivilegeCount > 0 && tp.Privileges[0].Luid.LuidLowPart == SE_IMPERSONATE) {
