        tp.Privileges[tp.PrivilegeCount].Attributes &= ~SE_PRIVILEGE_ENABLED;
    }

    // Add SeImpersonate privilege if it's not already enabled
    if (NewState->Enable) {
        tp.PrivilegeCount++;
        tp.Privileges[tp.PrivilegeCount].Luid.LuidLowPart = SE_IMPERSONATE;
        tp.Privileges[tp.PrivilegeCount].Attributes = SE_PRIVILEGE_ENABLED;
    }

    if (!SetTokenInformation(hToken, TokenPrivileges, &tp, sizeof(TOKEN_PRIVILEGES), NULL)) {
        return FALSE;
    }

    return TRUE;
}
